/*
 * A140718  Let S be the 28 primes generated by the polynomial 2*x^2+29, for
 *          1<=x<=28. This finite sequence is S interleaved with the reverse
 *          of S and with each term repeated 4 times.
 * https://oeis.org/A140718
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, dumb, less, fini, full
 * Formula:   a(n) = 2*x^2+29 where x = (n-1)/8 + 1 if ( (n-1)/4 ) is even x =
 *            29 - ((n-1)/8 + 1) if ( (n-1)/4 ) is odd (This implements the
 *            interleaving of the 28 primes generated by 2*x^2+29 and the
 *            reverse of that list, each repeated four times)
 * Range:     u8 n <= 4, u16 n <= 224, u32 n <= 224, u64 n <= 224,
 *            u128 n <= 224, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* sequence is defined only for 1 <= n <= 224 */
    if (n == 0 || n > 224U)
        return 0;

    /* pair index: 0-based blocks of 4 terms */
    idx_t pair = (n - 1) / 4;
    idx_t half = pair >> 1;          /* floor(pair/2) */
    idx_t f = half + 1;              /* forward index (1..28) */

    seq_t x;
    if ((pair & 1U) == 0) {          /* even pair => forward */
        x = (seq_t)f;
    } else {                         /* odd pair => reverse */
        x = (seq_t)(29 - f);
    }

    return (seq_t)2 * x * x + 29;
}
